INSERT OR REPLACE INTO questions (id, external_code, subject_id, topic_id, gate_year, gate_set, gate_question_number, question_type, marks, difficulty, question_html, options, correct_answer, is_mta, answer_verified, tags, has_image, source_volume, source_page) VALUES ('q_vol2_1_23_5', 'vol2-1.23.5', 'sub_algorithms', 'top_algorithms_identify-function', 1994, NULL, '6', 'DESCRIPTIVE', 1.0, 'normal', 'What function of   ,   is computed by this program?

  Function what(x, n:integer): integer:
 Var
    value : integer
  begin
    value := 1
       if n > 0 then
