INSERT OR REPLACE INTO questions (id, external_code, subject_id, topic_id, gate_year, gate_set, gate_question_number, question_type, marks, difficulty, question_html, options, correct_answer, is_mta, answer_verified, tags, has_image, source_volume, source_page) VALUES ('q_vol2_2_21_4', 'vol2-2.21.4', 'sub_compiler-design', 'top_compiler-design_parameter-passing', 1990, NULL, '11a', 'DESCRIPTIVE', 1.0, 'normal', 'What does the following program output?

 program module (input, output);
  var
    a:array [1...5] of integer;
       i, j: integer;
  procedure unknown (var b: integer, var c: integer);
  var
     i:integer;
  begin
     for i := 1 to 5 do a[i] := i;
    b:= 0; c := 0
     for i := 1 to 5 do write (a[i]);
     writeln();
    a[3]:=11; a[1]:=11;
     for i:=1 to 5 do a [i] := sqr(a[i]);
     writeln(c,b); b := 5; c := 6;
  end;
