   i:=1; j:=3; unknown (a[i], a[j]);
   for i:=1 to 5 do write (a[i]);
  end;', '{}', 'N/A', 0, 0, 'gate1990,descriptive,compiler-design,runtime-environment,parameter-passing', 0, 'filter1_vol2.pdf', 162);
