INSERT OR REPLACE INTO questions (id, external_code, subject_id, topic_id, gate_year, gate_set, gate_question_number, question_type, marks, difficulty, question_html, options, correct_answer, is_mta, answer_verified, tags, has_image, source_volume, source_page) VALUES ('q_vol3_3_21_3', 'vol3-3.21.3', 'sub_databases', 'top_databases_sql', 1990, NULL, '10-a', 'DESCRIPTIVE', 1.0, 'normal', 'Consider the following relational database:

     employees (eno, ename, address, basic-salary)
      projects (pno, pname, nos-of-staffs-allotted)
     working (pno, eno, pjob)

