INSERT OR REPLACE INTO questions (id, external_code, subject_id, topic_id, gate_year, gate_set, gate_question_number, question_type, marks, difficulty, question_html, options, correct_answer, is_mta, answer_verified, tags, has_image, source_volume, source_page) VALUES ('q_vol3_3_21_23', 'vol3-3.21.23', 'sub_databases', 'top_databases_sql', 2007, NULL, '61', 'MCQ', 2.0, 'normal', 'Consider  the  table employee(empId, name, department, salary) and the two queries         below.
