    var
   REM, EXPONENT:integer;
   BINARY :integer;
    begin
       if(N>=-8) and (N<=+7) then
      begin
                if N<0 then
          N:=A;
        BINARY:=0;
       EXPONENT:=1;
         while N<>0 do
        begin
